import React,{useState} from "react";
import api from "../services/api";

export default function Passbook(){
  const [id,setId]=useState("3");
  const [data,setData]=useState(null);
  const [err,setErr]=useState("");

  const load=async e=>{
    e?.preventDefault();
    try{
      setErr("");
      setData((await api.get(`/members/${id}/passbook`)).data);
    }catch(e){setData(null);setErr(e.response?.data?.message||"Passbook not found.");}
  };

  return (
    <>
      <div className="page-head"><div><span className="eyebrow">MEMBER LEDGER</span><h2>Passbook</h2><p>View a member's share capital and transaction history.</p></div></div>
      <form className="inline-form" onSubmit={load}><input value={id} onChange={e=>setId(e.target.value)} placeholder="Member ID (e.g. 3)"/><button className="primary">View passbook</button></form>
      {err&&<div className="alert">{err}</div>}
      {data&&<div className="passbook">
        <div className="panel pass-head"><div><span>MEMBER</span><h3>{data.member?.name}</h3><small>{data.member?.memberId} • {data.member?.village}</small></div><div className="amount"><span>Share Capital</span><b>₹{data.shareCapital}</b></div></div>
        <div className="stats-grid mini"><div className="stat-card"><div><span>Transactions</span><strong>{data.procurementCount}</strong></div></div><div className="stat-card"><div><span>Total Procurement</span><strong>₹{data.totalProcurementValue}</strong></div></div></div>
        <div className="panel"><h3>Transactions</h3><table><thead><tr><th>Date</th><th>Commodity</th><th>Quantity</th><th>Total</th><th>Payment</th></tr></thead><tbody>{(data.transactions||[]).map(p=><tr key={p.id}><td>{p.procurementDate}</td><td>{p.commodity}</td><td>{p.quantityKg} kg</td><td>₹{p.totalAmount}</td><td><span className="badge pending">{p.paymentStatus}</span></td></tr>)}</tbody></table></div>
      </div>}
    </>
  );
}
